insert into public.coaches (id, user_id, is_active, city, category, data) values ('coach-1', 'user-coach-1', true, 'Paris', 'Sport & Fitness', '{"id":"coach-1","userId":"user-coach-1","name":"Marcus Thorne","title":"Coach Haute Performance & Force Athlétique","bio":"Spécialisé dans l''entraînement athlétique de haute performance et le conditionnement métabolique. J''aide les personnes motivées à franchir leurs paliers grâce à une programmation basée sur la science du mouvement et des techniques d''intensité de niveau élite. Que vous prépariez une compétition ou une remise en forme exigeante, nous atteindrons vos objectifs ensemble.","photo":"https://images.unsplash.com/photo-1568602471122-7832951cc4c5?w=800&auto=format&fit=crop&q=80","coverPhoto":"https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=1200&auto=format&fit=crop&q=80","rating":4.9,"reviewCount":128,"experienceYears":8,"hourlyRate":85,"isElite":true,"isAvailable":true,"location":"Paris & Île-de-France","city":"Paris","postalCode":"75008","address":"Studio Élite, 12 Rue du Faubourg Saint-Honoré, 75008 Paris","latitude":48.8698,"longitude":2.3185,"interventionRadiusKm":20,"interventionZone":"Paris intra-muros et banlieue ouest (20 km)","formats":["online","home","partner_gym","outdoor","coach_location"],"formatPrices":{"online":75,"home":95,"partner_gym":85,"outdoor":80,"coach_location":85},"isOnlineCoaching":true,"isInPersonCoaching":true,"verificationStatus":"verified","verificationDocs":[{"id":"doc-1","coachId":"coach-1","type":"diploma","title":"Master STAPS Préparation Physique et Mentale","status":"approved","submittedAt":"2025-04-10T10:00:00Z","verifiedAt":"2025-04-11T14:00:00Z"},{"id":"doc-2","coachId":"coach-1","type":"cert","title":"CSCS (Certified Strength and Conditioning Specialist)","status":"approved","submittedAt":"2025-04-10T10:00:00Z","verifiedAt":"2025-04-11T14:00:00Z"},{"id":"doc-3","coachId":"coach-1","type":"insurance","title":"Assurance RC Professionnelle Sport - Allianz","status":"approved","submittedAt":"2025-04-10T10:00:00Z","verifiedAt":"2025-04-11T14:00:00Z"}],"packs":[{"id":"pack-1","name":"Séance Unitaire","sessionsCount":1,"discountPercent":0,"pricePerSession":85,"totalPrice":85},{"id":"pack-5","name":"Pack Élan (5 séances)","sessionsCount":5,"discountPercent":10,"pricePerSession":76.5,"totalPrice":382.5,"popular":true},{"id":"pack-10","name":"Pack Transformation (10 séances)","sessionsCount":10,"discountPercent":18,"pricePerSession":69.7,"totalPrice":697}],"specialties":["Force","HIIT","Perte de Poids","Conditionnement","Préparation physique"],"category":"Sport & Fitness","languages":["Français","Anglais"],"certifications":["Master STAPS Préparation Physique","CSCS Certified","Precision Nutrition L2"],"nextAvailabilitySummary":"Demain dès 09:00","videoLink":"https://zoom.us/j/findmycoach-marcus-alex-live","galleryPhotos":["https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=800&auto=format&fit=crop&q=80","https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=800&auto=format&fit=crop&q=80","https://images.unsplash.com/photo-1540497077202-7c8a3999166f?w=800&auto=format&fit=crop&q=80"],"isProfileComplete":true,"isActive":true}'::jsonb) on conflict (id) do update set data = excluded.data, is_active = excluded.is_active, city = excluded.city, category = excluded.category;
