insert into public.coaches (id, user_id, is_active, city, category, data) values ('coach-3', 'user-coach-3', true, 'Bordeaux', 'Sport & Fitness', '{"id":"coach-3","userId":"user-coach-3","name":"Alex Rivera","title":"Force Athlétique & CrossFit","bio":"Ancien gymnaste de haut niveau et coach CrossFit L3. Mon approche repose sur la mécanique gestuelle irréprochable, le gainage fondamental et la puissance explosive pour bâtir un corps résistant et sans blessure.","photo":"https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=800&auto=format&fit=crop&q=80","coverPhoto":"https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=1200&auto=format&fit=crop&q=80","rating":4.9,"reviewCount":86,"experienceYears":5,"hourlyRate":80,"isElite":true,"isAvailable":true,"location":"Bordeaux & En ligne","city":"Bordeaux","postalCode":"33000","latitude":44.8378,"longitude":-0.5792,"interventionRadiusKm":25,"interventionZone":"Bordeaux Métropole et Bassin d’Arcachon","formats":["partner_gym","outdoor","home","online"],"formatPrices":{"online":70,"home":90,"partner_gym":80,"outdoor":75},"isOnlineCoaching":true,"isInPersonCoaching":true,"verificationStatus":"verified","specialties":["Force","CrossFit","Mobilité","Gainage","Conditionnement"],"category":"Sport & Fitness","languages":["Français"],"certifications":["BPJEPS AF Mention Haltérophilie","CrossFit Level 3 Trainer"],"nextAvailabilitySummary":"Demain dès 10:30","isProfileComplete":true,"isActive":true}'::jsonb) on conflict (id) do update set data = excluded.data, is_active = excluded.is_active, city = excluded.city, category = excluded.category;
insert into public.coaches (id, user_id, is_active, city, category, data) values ('coach-4', 'user-coach-4', true, 'Lyon', 'Bien-être & Posture', '{"id":"coach-4","userId":"user-coach-4","name":"Elena Rodriguez","title":"Yoga Vinyasa, Yin & Breathwork","bio":"Spécialiste Vinyasa Flow, Yin Yoga et régulation du système nerveux. Mes séances ciblent la souplesse profonde, le renforcement postural et la clarté mentale absolue pour performer au quotidien sans burn-out.","photo":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=800&auto=format&fit=crop&q=80","coverPhoto":"https://images.unsplash.com/photo-1545205597-3d9d02c29597?w=1200&auto=format&fit=crop&q=80","rating":5,"reviewCount":112,"experienceYears":7,"hourlyRate":110,"isElite":true,"isAvailable":true,"location":"Lyon & En ligne","city":"Lyon","postalCode":"69001","latitude":45.764,"longitude":4.8357,"interventionRadiusKm":15,"interventionZone":"Lyon Centre et Grand Lyon","formats":["online","coach_location","home","outdoor"],"formatPrices":{"online":90,"coach_location":110,"home":125,"outdoor":100},"isOnlineCoaching":true,"isInPersonCoaching":true,"verificationStatus":"verified","specialties":["Yoga","Méditation","Breathwork","Bien-être","Mobilité"],"category":"Bien-être & Posture","languages":["Français","Espagnol","Anglais"],"certifications":["E-RYT 500 Yoga Alliance","Pranayama Master Coach"],"nextAvailabilitySummary":"Vendredi dès 09:00","isProfileComplete":true,"isActive":true}'::jsonb) on conflict (id) do update set data = excluded.data, is_active = excluded.is_active, city = excluded.city, category = excluded.category;
insert into public.coaches (id, user_id, is_active, city, category, data) values ('coach-5', 'user-coach-5', true, 'Lille', 'Sport & Fitness', '{"id":"coach-5","userId":"user-coach-5","name":"David Chen","title":"Musculation, Force & Diète Sportive","bio":"Préparateur physique pour athlètes et pratiquants exigeants. Optimisation de la surcharge progressive, volume d’entraînement périodisé et diététique ciblée pour des gains musculaires rapides et sains.","photo":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=800&auto=format&fit=crop&q=80","coverPhoto":"https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?w=1200&auto=format&fit=crop&q=80","rating":4.8,"reviewCount":64,"experienceYears":9,"hourlyRate":65,"isElite":false,"isAvailable":true,"location":"Lille & En ligne","city":"Lille","postalCode":"59000","latitude":50.6292,"longitude":3.0573,"interventionRadiusKm":20,"interventionZone":"Lille Métropole et périphérie","formats":["partner_gym","home","online"],"isOnlineCoaching":true,"isInPersonCoaching":true,"verificationStatus":"verified","specialties":["Hypertrophie","Force","Diète Sportive","Musculation"],"category":"Sport & Fitness","languages":["Français","Mandarin"],"certifications":["Diplôme FFFMR","Certified Strength Coach"],"nextAvailabilitySummary":"Samedi dès 10:00","isProfileComplete":true,"isActive":true}'::jsonb) on conflict (id) do update set data = excluded.data, is_active = excluded.is_active, city = excluded.city, category = excluded.category;
insert into public.coaches (id, user_id, is_active, city, category, data) values ('coach-6', 'user-coach-6', true, 'Paris', 'Business & Leadership', '{"id":"coach-6","userId":"user-coach-6","name":"Mike Ross","title":"Executive Coach & Leadership Stratégique","bio":"Ex-cadre dirigeant et executive coach certifié HEC. J’accompagne les fondateurs, directeurs et managers dans la prise de décision stratégique, la résilience mentale et la prise de parole percutante.","photo":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=800&auto=format&fit=crop&q=80","coverPhoto":"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=1200&auto=format&fit=crop&q=80","rating":4.9,"reviewCount":78,"experienceYears":11,"hourlyRate":140,"isElite":true,"isAvailable":true,"location":"Paris & En ligne","city":"Paris","postalCode":"75016","latitude":48.8606,"longitude":2.2789,"interventionRadiusKm":30,"interventionZone":"Paris & La Défense (Sièges d’entreprise)","formats":["online","corporate","coach_location"],"formatPrices":{"online":140,"corporate":180,"coach_location":150},"isOnlineCoaching":true,"isInPersonCoaching":true,"verificationStatus":"verified","specialties":["Leadership","Carrière","Mindset","Gestion du Stress","Négociation"],"category":"Business & Leadership","languages":["Français","Anglais"],"certifications":["Executive Coaching HEC Paris","ICF Master Certified Coach (MCC)"],"nextAvailabilitySummary":"Lundi dès 11:00","isProfileComplete":true,"isActive":true}'::jsonb) on conflict (id) do update set data = excluded.data, is_active = excluded.is_active, city = excluded.city, category = excluded.category;
insert into public.coaches (id, user_id, is_active, city, category, data) values ('coach-7', 'user-coach-7', true, 'Paris', 'Mindset & Discipline', '{"id":"coach-7","userId":"user-coach-7","name":"Thomas Vasseur","title":"Préparateur Mental & Focus sous Pression","bio":"Préparateur mental de sportifs de haut niveau et d’entrepreneurs. Développez une discipline inébranlable, surmontez le doute et apprenez à performer sous pression maximale.","photo":"https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=800&auto=format&fit=crop&q=80","coverPhoto":"https://images.unsplash.com/photo-1499209974431-9dddcece7f88?w=1200&auto=format&fit=crop&q=80","rating":4.9,"reviewCount":52,"experienceYears":7,"hourlyRate":95,"isElite":true,"isAvailable":true,"location":"En ligne / Visio","city":"Paris","latitude":48.8566,"longitude":2.3522,"interventionRadiusKm":0,"interventionZone":"100% En ligne / Visio mondiale","formats":["online"],"isOnlineCoaching":true,"isInPersonCoaching":false,"verificationStatus":"verified","specialties":["Mindset","Gestion du Stress","Motivation","Discipline mentale","Focus"],"category":"Mindset & Discipline","languages":["Français","Anglais"],"certifications":["Master Psychologie de la Performance","Certificat Préparation Mentale INSEP"],"nextAvailabilitySummary":"Demain dès 14:00","isProfileComplete":true,"isActive":true}'::jsonb) on conflict (id) do update set data = excluded.data, is_active = excluded.is_active, city = excluded.city, category = excluded.category;
insert into public.coaches (id, user_id, is_active, city, category, data) values ('coach-8', 'user-coach-8', true, 'Nantes', 'Carrière & Évolution', '{"id":"coach-8","userId":"user-coach-8","name":"Clara Martin","title":"Coach Carrière & Transition Professionnelle","bio":"Consultante RH et coach certifiée en reconversion professionnelle. Je vous aide à définir votre feuille de route professionnelle, négocier votre rémunération et réussir vos entretiens clés.","photo":"https://images.unsplash.com/photo-1580489944761-15a19d654956?w=800&auto=format&fit=crop&q=80","coverPhoto":"https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1200&auto=format&fit=crop&q=80","rating":4.8,"reviewCount":41,"experienceYears":6,"hourlyRate":90,"isElite":false,"isAvailable":true,"location":"Nantes & En ligne","city":"Nantes","postalCode":"44000","latitude":47.2184,"longitude":-1.5536,"interventionRadiusKm":20,"interventionZone":"Nantes et agglomération nantaise","formats":["online","coach_location","corporate"],"formatPrices":{"online":85,"coach_location":95,"corporate":120},"isOnlineCoaching":true,"isInPersonCoaching":true,"verificationStatus":"verified","specialties":["Carrière","Leadership","Mindset","Entrepreneuriat","Prise de parole"],"category":"Carrière & Évolution","languages":["Français"],"certifications":["Certification RNCP Coach Professionnel","Praticienne MBTI"],"nextAvailabilitySummary":"Jeudi dès 10:00","isProfileComplete":true,"isActive":true}'::jsonb) on conflict (id) do update set data = excluded.data, is_active = excluded.is_active, city = excluded.city, category = excluded.category;
insert into public.reviews (id, coach_id, client_id, booking_id, is_hidden, data) values ('rev-1', 'coach-1', 'user-client-1', 'booking-past-1', false, '{"id":"rev-1","bookingId":"booking-past-1","clientId":"user-client-1","clientName":"Alex Rivers","clientAvatar":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=80","coachId":"coach-1","rating":5,"comment":"Marcus est exceptionnel. Son analyse de la posture et sa programmation personnalisée ont transformé ma force et mon endurance. Je recommande les yeux fermés !","createdAt":"Il y a 3 jours","categoryTag":"Sport & Fitness"}'::jsonb) on conflict (id) do nothing;
insert into public.reviews (id, coach_id, client_id, booking_id, is_hidden, data) values ('rev-2', 'coach-1', 'user-client-2', 'booking-demo-2', false, '{"id":"rev-2","bookingId":"booking-demo-2","clientId":"user-client-2","clientName":"Camille Laurent","clientAvatar":"https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&auto=format&fit=crop&q=80","coachId":"coach-1","rating":4.8,"comment":"Excellente séance de conditionnement métabolique. Pédagogie claire, intensité calibrée avec soin.","createdAt":"Il y a 1 semaine","categoryTag":"Sport & Fitness"}'::jsonb) on conflict (id) do nothing;
insert into public.reviews (id, coach_id, client_id, booking_id, is_hidden, data) values ('rev-3', 'coach-2', 'user-client-1', 'booking-past-2', false, '{"id":"rev-3","bookingId":"booking-past-2","clientId":"user-client-1","clientName":"Alex Rivers","clientAvatar":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=80","coachId":"coach-2","rating":5,"comment":"Un accompagnement nutritionnel ultra pragmatique et bienveillant. Fini les régimes yoyo !","createdAt":"Il y a 12 jours","categoryTag":"Nutrition & Diététique"}'::jsonb) on conflict (id) do nothing;
